import marimo

app = marimo.App()


@app.function
def add(a, b):
    return a + b


@app.function
def sub(a, b):
    return a - b


@app.function
def mul(a, b):
    return a * b


@app.cell
def _():
    def test_q1_comprehension():
        assert [add for add in range(3)] == [0, 1, 2]

    def test_q1_closure():
        def inner():
            return sub(2, 1)

        assert inner() == 1

    class Expected:
        value = mul(2, 3)

    def test_q1_class():
        assert Expected.value == 6

    return

